package ma.translogix.model;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A client invoice. Issue [C3]. Amounts are BigDecimal (never double) and computed by FactureService.
 * missionId stays null until Hamid's Mission exists ([H2]); referenceTrajet holds the trip reference meanwhile.
 */
public class Facture {
    private Long id;
    /** FACT-YYYY-NNN, generated by FactureService. */
    private String numero;
    private Long clientId;
    private Long missionId;
    private String referenceTrajet;
    private BigDecimal montantHT;
    /** Percentage, e.g. 14.00 for 14 %. */
    private BigDecimal tauxTva;
    private BigDecimal montantTva;
    private BigDecimal montantTtc;
    private LocalDate dateEmission;
    private LocalDate dateEcheance;
    private StatutFacture statut = StatutFacture.EN_ATTENTE;

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getNumero() { return numero; }
    public void setNumero(String numero) { this.numero = numero; }

    public Long getClientId() { return clientId; }
    public void setClientId(Long clientId) { this.clientId = clientId; }

    public Long getMissionId() { return missionId; }
    public void setMissionId(Long missionId) { this.missionId = missionId; }

    public String getReferenceTrajet() { return referenceTrajet; }
    public void setReferenceTrajet(String referenceTrajet) { this.referenceTrajet = referenceTrajet; }

    public BigDecimal getMontantHT() { return montantHT; }
    public void setMontantHT(BigDecimal montantHT) { this.montantHT = montantHT; }

    public BigDecimal getTauxTva() { return tauxTva; }
    public void setTauxTva(BigDecimal tauxTva) { this.tauxTva = tauxTva; }

    public BigDecimal getMontantTva() { return montantTva; }
    public void setMontantTva(BigDecimal montantTva) { this.montantTva = montantTva; }

    public BigDecimal getMontantTtc() { return montantTtc; }
    public void setMontantTtc(BigDecimal montantTtc) { this.montantTtc = montantTtc; }

    public LocalDate getDateEmission() { return dateEmission; }
    public void setDateEmission(LocalDate dateEmission) { this.dateEmission = dateEmission; }

    public LocalDate getDateEcheance() { return dateEcheance; }
    public void setDateEcheance(LocalDate dateEcheance) { this.dateEcheance = dateEcheance; }

    public StatutFacture getStatut() { return statut; }
    public void setStatut(StatutFacture statut) { this.statut = statut; }
}
